<script lang="ts">
  import { onMount } from "svelte";
  import { atlas } from "$lib/atlas/connection.svelte";
  import { statuses, formatValue, kindColors, type GraphNode } from "$lib/atlas/contracts";
  import AtlasSpace from "./AtlasSpace.svelte";
  let view = $state<"galaxy" | "command" | "sales" | "vault">("galaxy");
  let selected = $state<GraphNode | null>(null);
  let markdown = $state(""); let documentError = $state(""); let filter = $state(""); let token = $state("");
  let saving = $state(""); let feedback = $state(""); let revision = 0;
  const labels: Record<string, string> = { new: "Novos", qualified: "Qualificados", proposal: "Propostas", won: "Ganhos", lost: "Perdidos" };
  let nodes = $derived((atlas.graph?.nodes ?? []).filter(n => `${n.label} ${n.path} ${n.tags.join(" ")}`.toLowerCase().includes(filter.toLowerCase())));
  let leads = $derived(nodes.filter(n => n.kind === "lead"));
  onMount(() => atlas.start());
  async function select(node: GraphNode) { selected = node; markdown = ""; documentError = ""; const current = ++revision; try { const text = await atlas.read(node.path); if (current === revision) markdown = text; } catch (error) { if (current === revision) documentError = String(error); } }
  async function move(node: GraphNode, status: string) { saving = node.id; feedback = ""; try { await atlas.updateStatus(node, status); feedback = `${node.label}: ${labels[status]}. Markdown atualizado.`; } catch (error) { feedback = String(error); } finally { saving = ""; } }
</script>
<div class="atlas-console">
  <header class="atlas-head"><div><span class="eyebrow">ATLAS / AGENT OS</span><h2>A sua empresa, aumentada.</h2><p>Identidades, conhecimento e operações num espaço vivo.</p></div><a href="/atlas">Conhecer o ecossistema ↗</a></header>
  <div class="statusbar"><span class:live={atlas.connected} class="signal"></span><strong>{atlas.connected ? "Telemetria em direto" : "Telemetria desligada"}</strong><span>{atlas.source}</span><span class="spacer"></span><span>{atlas.graph?.nodes.length ?? 0} documentos · {atlas.graph?.links.length ?? 0} ligações</span><button onclick={() => atlas.refresh()} disabled={atlas.loading}>{atlas.loading ? "A ler…" : "Atualizar Vault"}</button></div>
  <div class="connection"><label for="atlas-token">Ligação ao daemon</label><input id="atlas-token" type="password" bind:value={token} placeholder="ATLAS_TOKEN · apenas nesta sessão" autocomplete="off" /><button onclick={() => atlas.configure(token)}>Ligar</button><small>127.0.0.1:18790 · token mantido apenas em memória</small></div>
  {#if atlas.error}<div class="notice" role="status"><strong>Vault indisponível.</strong> {atlas.error}<p>Prepare <code>~/.atlas/vault</code> com o <code>vault-starter</code> de atlas-workforce. Para o navegador, inicie <code>atlas daemon</code> e ligue com o respetivo token.</p></div>{/if}
  <nav class="views" aria-label="Atlas Command Surface">{#each [["galaxy", "◉", "Galaxy 3D"], ["command", "⌘", "Command 3D"], ["sales", "↗", "Sales OS"], ["vault", "◇", "Vault & Brain"]] as [id, icon, name]}<button class:active={view === id} onclick={() => view = id as typeof view}><span>{icon}</span>{name}</button>{/each}<input type="search" aria-label="Pesquisar documentos do Vault" placeholder="Pesquisar no Vault…" bind:value={filter} /></nav>
  {#if view === "sales"}
    <div class="crm-title"><div><span class="eyebrow">ATLAS SALES OS</span><h3>Relações que movem o negócio.</h3></div><span>{leads.length} fichas no Vault</span></div>
    {#if feedback}<p class="notice" role="status">{feedback}</p>{/if}
    <div class="kanban">{#each statuses as status}<section class="column"><header><span>{labels[status]}</span><b>{leads.filter(n => n.frontmatter.status === status).length}</b></header>{#each leads.filter(n => n.frontmatter.status === status) as lead}<article class="lead"><button class="lead-name" onclick={() => select(lead)}>{lead.label}</button><strong class="money">{formatValue(lead)}</strong><p>{String(lead.frontmatter.next_action ?? "Definir próxima ação")}</p><small>@{String(lead.frontmatter.owner_agent ?? "sem responsável")}</small><label>Etapa<select aria-label={`Etapa de ${lead.label}`} disabled={saving === lead.id} value={status} onchange={event => move(lead, event.currentTarget.value)}>{#each statuses as target}<option value={target}>{labels[target]}</option>{/each}</select></label></article>{/each}</section>{/each}</div>
    {#if !leads.length}<p class="empty">Sem fichas de CRM. Adicione Markdown em <code>packs/crm-sales-os/leads/</code> com status, value, currency, owner_agent e next_action.</p>{/if}
    {#if leads.some(n => !statuses.includes(n.frontmatter.status as typeof statuses[number]))}<p class="notice">Existem fichas com etapa desconhecida. Reveja o campo <code>status</code> no Vault.</p>{/if}
  {:else}
    <div class="workspace"><section class="canvas-panel">{#if view === "vault"}<div class="document-grid">{#each nodes as node}<button onclick={() => select(node)}><span style={`color:${kindColors[node.kind]}`}>{node.kind.toUpperCase()}</span><strong>{node.label}</strong><small>{node.path}</small></button>{/each}</div>{:else if atlas.graph && atlas.graph.nodes.length}<AtlasSpace graph={atlas.graph} mode={view} states={atlas.agents} onselect={select} /><div class="space-caption"><span>{view === "galaxy" ? "O conhecimento tem uma arquitetura." : "Cada agente, uma estação de trabalho."}</span><small>Arraste para orbitar · roda para aproximar · clique para abrir</small></div>{:else}<div class="empty-orbit"><div class="orbital">A</div><h3>O seu universo começa no Vault.</h3><p>Ligue o Atlas Agent ou abra o Vault na aplicação nativa para explorar os seus agentes, projetos e memórias.</p></div>{/if}</section><aside class="documents"><span class="eyebrow">{view === "command" ? "AGENTES EM OPERAÇÃO" : "EXPLORAR DOCUMENTOS"}</span><div class="node-list">{#each (view === "command" ? nodes.filter(n => n.kind === "agent") : nodes).slice(0, 500) as node}<button class:chosen={selected?.id === node.id} onclick={() => select(node)}><span class="node-dot" style={`background:${kindColors[node.kind]}`}></span><span>{node.label}<small>{node.kind}{atlas.agents[node.path.split("/").pop()?.replace(/\.md$/, "") ?? ""] ? " · " + atlas.agents[node.path.split("/").pop()?.replace(/\.md$/, "") ?? ""].type.replace("agent:", "") : ""}</small></span></button>{/each}</div>{#if nodes.length > 500}<small>Lista limitada a 500 resultados. Use a pesquisa.</small>{/if}<div class="legend">{#each Object.entries(kindColors) as [kind, color]}<span><i style={`background:${color}`}></i>{kind}</span>{/each}</div>{#if atlas.graph?.unresolved.length}<p class="unresolved">{atlas.graph.unresolved.length} WikiLinks por resolver</p>{/if}</aside></div>
  {/if}
  {#if selected}<section class="detail"><header><div><span class="eyebrow">{selected.kind} / {selected.path}</span><h3>{selected.label}</h3></div><button onclick={() => { selected = null; revision++; }}>Fechar</button></header>{#if documentError}<p class="notice">{documentError}</p>{/if}{#if markdown}<pre>{markdown}</pre>{:else}<pre>{JSON.stringify(selected.frontmatter, null, 2)}</pre>{/if}</section>{/if}
  <section class="event-strip"><span class="eyebrow">SINAIS DO RUNTIME</span>{#if !atlas.events.length}<p>Nenhum evento recebido nesta sessão. A atividade é apresentada quando o runtime a emite.</p>{/if}{#each atlas.events.slice(0, 6) as event}<div><time>{new Date(event.timestamp).toLocaleTimeString("pt-BR")}</time><b>@{event.agentSlug}</b><span>{event.type}</span></div>{/each}</section>
</div>
<style>
  .atlas-console{height:100%;overflow:auto;background:#080e19;color:#dbe5ef;padding:28px;font-family:Inter,system-ui,sans-serif}.atlas-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.eyebrow{font-size:10px;letter-spacing:.18em;color:#d7b773;font-weight:700}.atlas-head h2{font-size:30px;letter-spacing:-.045em;margin:8px 0}.atlas-head p{font-size:12px;color:#8193aa}.atlas-head a{font-size:11px;color:#d7b773;border-bottom:1px solid #6d5c37;padding-bottom:5px}.statusbar,.connection{display:flex;gap:12px;align-items:center;flex-wrap:wrap;padding:12px 0;font-size:10px;color:#91a4b9;border-top:1px solid #233044}.statusbar strong{color:#dce6f0}.signal{width:6px;height:6px;border-radius:50%;background:#677587}.signal.live{background:#65d7b2;box-shadow:0 0 14px #65d7b2}.spacer{flex:1}.atlas-console button,.atlas-console select{font:inherit;border:1px solid #2a3b51;border-radius:5px;padding:7px 10px;background:#111e2e;color:#dce6f0;cursor:pointer}.atlas-console button:hover{border-color:#ba9c58}.atlas-console button:focus-visible,.atlas-console input:focus-visible,.atlas-console select:focus-visible{outline:2px solid #6bdbdf;outline-offset:3px}.atlas-console button:disabled{opacity:.5;cursor:wait}.atlas-console input{font:inherit;border:1px solid #2a3b51;border-radius:5px;padding:9px;background:#0c1726;color:#dce6f0}.connection input{width:220px}.connection small{color:#61778f}.notice{padding:14px;background:#172030;border:1px solid #35455a;font-size:11px;line-height:1.7;color:#bccbdc}.notice p{margin:5px 0 0}.views{display:flex;gap:6px;align-items:center;padding:20px 0;flex-wrap:wrap}.views button{display:flex;gap:10px;background:transparent;border-color:transparent;font-size:11px;padding:10px 13px}.views button.active{background:#24251f;color:#e3c384;border-color:#544c32}.views input{margin-left:auto;font-size:11px}.workspace{display:grid;grid-template-columns:minmax(0,1fr) 235px;min-height:470px;border:1px solid #233044;border-radius:9px;overflow:hidden}.canvas-panel{position:relative;min-width:0;background:radial-gradient(ellipse at 50% 40%,#142a3a 0,#0b1321 65%);min-height:470px}.documents{background:#0e1725;padding:18px;max-height:560px;display:flex;flex-direction:column;border-left:1px solid #233044}.node-list{overflow:auto;flex:1;margin:15px -5px}.node-list button{width:100%;display:flex;gap:10px;text-align:left;align-items:center;border:0;background:none;font-size:11px;padding:10px 5px}.node-list button.chosen{background:#202c3d}.node-dot{width:5px;height:5px;border-radius:50%;flex:none}.node-list small{display:block;color:#6f849b;font-size:9px;margin-top:3px}.legend{display:flex;gap:8px;flex-wrap:wrap;font-size:9px;color:#7f94ad}.legend span{display:flex;gap:4px;align-items:center}.legend i{width:4px;height:4px;border-radius:50%}.unresolved{font-size:10px;color:#d5b378;margin-top:14px}.space-caption{position:absolute;bottom:18px;left:20px;pointer-events:none}.space-caption span{font-size:13px;color:#d6c49a;display:block}.space-caption small{font-size:9px;color:#70899d;display:block;margin-top:5px}.empty-orbit{height:100%;display:flex;align-items:center;justify-content:center;flex-direction:column;min-height:470px;text-align:center;padding:30px}.orbital{display:grid;place-items:center;width:105px;height:105px;border:1px solid #7f6c41;border-radius:50%;box-shadow:0 0 0 25px #c6a65a06,0 0 0 65px #c6a65a04;color:#dcbd77;font-size:40px}.empty-orbit h3{margin-top:50px;font-size:20px;font-weight:500;letter-spacing:-.03em}.empty-orbit p{max-width:350px;font-size:11px;line-height:1.8;color:#7b93aa}.document-grid{padding:20px;display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:10px;max-height:540px;overflow:auto}.document-grid button{text-align:left;padding:16px;min-width:0}.document-grid strong,.document-grid small{display:block;margin-top:8px;overflow-wrap:anywhere}.document-grid span{font-size:9px;letter-spacing:.1em}.document-grid strong{font-size:12px}.document-grid small{font-size:9px;color:#70869b}.crm-title{display:flex;justify-content:space-between;align-items:center;margin:10px 0 20px}.crm-title h3{font-weight:500;font-size:20px;margin-top:9px}.crm-title>span{font-size:10px;color:#748ba3}.kanban{display:grid;grid-template-columns:repeat(5,minmax(170px,1fr));gap:10px;overflow-x:auto}.column{border:1px solid #26364b;border-radius:7px;background:#0e1725;min-height:300px}.column>header{padding:14px;display:flex;justify-content:space-between;color:#a8bbd1;font-size:11px;border-bottom:1px solid #26364b}.column>header b{font-size:10px;color:#d3b674}.lead{padding:14px;margin:9px;background:#142133;border:1px solid #293c53;border-radius:5px}.lead .lead-name{font-size:12px;font-weight:600;padding:0;border:0;background:none;text-align:left}.money{display:block;margin-top:14px;font-size:15px;color:#d5bb7d}.lead p{font-size:10px;line-height:1.6;color:#8ea5bc;margin:10px 0}.lead small{font-size:9px;color:#74b7bb;overflow-wrap:anywhere}.lead label{display:block;font-size:9px;color:#788fa6;margin-top:16px}.lead select{width:100%;font-size:10px;margin-top:5px}.empty{padding:24px;color:#8b9fb6;font-size:12px}.detail{margin-top:15px;padding:20px;background:#111c2c;border:1px solid #293c53;border-radius:7px}.detail header{display:flex;justify-content:space-between;gap:20px;align-items:center}.detail h3{font-size:18px;margin-top:9px}.detail pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px;line-height:1.8;color:#a6b9cf;margin-top:20px;max-height:350px;overflow:auto}.event-strip{padding:22px 0}.event-strip p{font-size:10px;color:#6b8199;margin-top:10px}.event-strip>div{display:flex;gap:16px;align-items:center;font-size:10px;border-bottom:1px solid #1a293b;padding:9px 0}.event-strip time{color:#617c95}.event-strip b{color:#b9c9da;font-weight:500}.event-strip>div>span{color:#61bdc5}@media(max-width:900px){.atlas-console{padding:18px}.workspace{grid-template-columns:1fr}.documents{max-height:230px;border-left:0;border-top:1px solid #233044}.atlas-head{align-items:flex-start;gap:15px}.atlas-head h2{font-size:24px}.statusbar{gap:9px}.views input{width:100%;margin-left:0}.kanban{grid-template-columns:repeat(5,200px)}}
</style>
